NAME = 'GerLeoNA28: Leonberger Bibel, NT (NA28)'
BOOK = 'II Peter'

CHAPTERS = {
    1: {
        1: 'Simeon Petrus, ein Knecht und Apostel von Jesus Christus. /An diejenigen, die einen uns ebenbürtigen Glauben erhalten haben durch die Gerechtigkeit unseres Gottes und Retters Jesus Christus: /',
        2: 'Gnade und Frieden mögen euch vermehrt werden durch die Erkenntnis Gottes und Jesu, unseres Herrn!',
        3: 'Weil seine göttliche Kraft uns alles geschenkt hat, was zum Leben und zur Frömmigkeit [notwendig ist], durch die Erkenntnis dessen, der uns berufen hat durch seine Herrlichkeit und sein Wesen …',
        4: 'dadurch hat er uns die kostbaren und größten Verheißungen geschenkt, damit ihr durch sie Teilhaber der göttlichen Natur werdet, nachdem ihr dem Verderben entflohen seid, das durch die Begierde in der Welt [ist].',
        5: 'Und aus eben diesem [Grund] unternehmt nun jede Anstrengung und unterstützt durch euren Glauben die Tugend, durch die Tugend wiederum die Kenntnis,',
        6: 'durch die Kenntnis wiederum die Enthaltsamkeit, durch die Enthaltsamkeit wiederum die Standhaftigkeit, durch die Standhaftigkeit wiederum die Frömmigkeit,',
        7: 'durch die Frömmigkeit wiederum die Geschwisterliebe, durch die Geschwisterliebe wiederum die Liebe.',
        8: 'Denn wenn diese [Dinge] bei euch vorhanden sind und zunehmen, dann machen sie euch weder träge noch untätig für die Erkenntnis unseres Herrn Jesus Christus.',
        9: 'Denn wem diese [Dinge] nicht präsent sind, der ist blind und kurzsichtig, da er die Reinigung von seinen früheren Sünden ‹vergessen hat›.',
        10: 'Darum, Geschwister: Strengt euch vielmehr an, eure Berufung und Erwählung sicher zu machen; wenn ihr nämlich das tut, strauchelt ihr gewiss niemals!',
        11: 'Denn auf diese Weise wird euch der Eingang in das ewige Reich unseres Herrn und Retters Jesus Christus reichlich zukommen.',
        12: 'Darum werde ich dafür sorgen, euch ständig daran zu erinnern, obwohl ihr es wisst und in der gegenwärtigen Wahrheit gefestigt seid.',
        13: 'Ich halte es aber für richtig, solange ich in diesem Zelt bin, euch durch Erinnerung aufzuwecken,',
        14: 'da ich weiß, dass das Ablegen meines Zeltes bald geschieht, wie mir auch unser Herr Jesus Christus angedeutet hat.',
        15: 'Ich werde mich aber bemühen, dass ihr auch nach meinem Abgang jederzeit [Anlass] habt, euch daran zu erinnern.',
        16: 'Denn nicht, weil wir ausgeklügelten Legenden gefolgt sind, haben wir euch die Kraft und Gegenwart unseres Herrn Jesus Christus bekannt gemacht, sondern weil wir Augenzeugen seiner Großartigkeit geworden sind.',
        17: 'Denn er hat von Gott dem Vater Ehre und Herrlichkeit erhalten, als von der großartigen Herrlichkeit folgende Stimme an ihn erging: „Dieser ist mein Sohn, mein geliebter [Sohn], an dem ich Gefallen habe.“',
        18: 'Und diese Stimme haben wir vom Himmel ergehen gehört, als wir zusammen mit ihm auf dem heiligen Berg waren.',
        19: 'Und wir halten das prophetische Wort [umso] fester – ihr tut gut daran, darauf zu achten wie auf eine Lampe, die an einem dunklen Ort scheint, bis der Tag anbricht und der Morgenstern aufgeht in euren Herzen.',
        20: 'Erkennt vor allem Folgendes: dass alle Weissagung der Schrift nicht aus eigener Deutung geschieht;',
        21: 'es ist nämlich noch nie eine Weissagung durch den Willen eines Menschen hervorgebracht worden, sondern vom heiligen Geist angetrieben haben Menschen von Gott her gesprochen.',
    },
    2: {
        1: 'Es waren aber auch falsche Propheten unter dem Volk, wie auch unter euch falsche Lehrer sein werden, welche Sekten des Verderbens einführen werden, indem sie sogar den Herrscher, der sie erkauft hat, verleugnen werden, sodass sie sich selbst ein schnelles Verderben zuziehen.',
        2: 'Und viele werden ihren Ausschweifungen folgen, derentwegen der Weg der Wahrheit in Verruf gebracht werden wird.',
        3: 'Und aus Habgier werden sie euch mit irreführenden Worten kaufen; ihnen zögert das Gericht seit Langem nicht, und ihr Verderben schlummert nicht.',
        4: 'Denn wenn Gott Engel, die gesündigt hatten, nicht verschonte, sondern sie mit Ketten des Dunkels in der Unterwelt eingesperrt und ans Gericht ausgeliefert hat, damit sie aufbewahrt werden,',
        5: 'und er die alte Welt nicht verschonte, sondern er Noah, den Prediger der Gerechtigkeit, als achten bewahrt hat, als er eine Flut über die Welt der Gottlosen brachte,',
        6: 'und er die Städte Sodom und Gomorra eingeäschert und zum Untergang verurteilt hat, um einen Vorgeschmack zu geben, was dem Gottlossein droht,',
        7: 'und er den gerechten Lot rettete, der unter dem ausschweifenden Lebenswandel der Gewissenlosen litt',
        8: '(denn [schon allein] durchs Zusehen und Zuhören quälte der Gerechte, der unter ihnen wohnte, Tag für Tag [seine] gerechte Seele mit [ihren] gesetzlosen Werken):',
        9: 'Der Herr weiß, die Frommen aus der Versuchung zu retten, die Ungerechten aber für den Tag des Gerichts aufzubewahren, damit sie bestraft werden.',
        10: 'Aber besonders diejenigen, die in befleckender Begierde hinter dem Fleisch hergehen und [Gottes] Herrschaft verachten. Verwegen [und] arrogant zittern sie nicht, während sie glorreiche Wesen niedermachen,',
        11: 'wohingegen Engel, die an Stärke und Kraft größer sind, beim Herrn kein lästerliches Urteil gegen sie vorbringen.',
        12: 'Aber diese [Leute] [sind] wie irrationale Tiere, mit natürlichen [Instinkten] zum Jagen und Töten geboren, und da sie über Dinge lästern, die sie nicht kennen, werden sie in ihrer Vergänglichkeit auch umkommen,',
        13: 'wobei sie mit dem Lohn der Ungerechtigkeit geschädigt werden. Sie halten das Schwelgen bei Tag für ein Vergnügen; [sie sind] Flecken und Runzeln, die in ihren Betrügereien schwelgen, während sie mit euch feiern;',
        14: 'sie haben Augen, die voller ehebrecherischer [Lust] [sind] und rastlos von Sünde [geleitet werden]; sie locken ungefestigte Seelen an; sie haben ein von der Habgier geübtes Herz; [sie sind] Kinder des Fluches.',
        15: 'Nachdem sie den geraden Weg verlassen haben, wurden sie verführt, da sie dem Weg von Balaam folgten, dem [Sohn] von Bosor, der den Lohn der Ungerechtigkeit liebte,',
        16: 'aber eine Strafe für die eigene Gesetzlosigkeit erhielt: Ein stimmloser Esel, der sich mit der Stimme eines Menschen äußerte, verhinderte die Dummheit des Propheten.',
        17: 'Diese [Leute] sind wasserlose Quellen und von Sturm getriebene Nebelschwaden, denen das Dunkel der Finsternis vorbehalten ist.',
        18: 'Denn sie äußern hochtrabendes, [aber zugleich] nichtssagendes [Zeug] und locken mit Begierden des Fleisches und Ausschweifungen diejenigen an, die eigentlich denen entfliehen, die im Irrtum leben',
        19: '[und] die ihnen Freiheit verheißen, obwohl sie selbst Knechte der Vergänglichkeit sind. Denn wem sich jemand unterwirft, dem ist er versklavt.',
        20: 'Denn wenn sie den Befleckungen der Welt durch die Erkenntnis des Herrn und Retters Jesus Christus entflohen sind, aber erneut in ihnen verwickelt wurden und sich ihnen unterworfen haben, dann sind für sie die letzten [Umstände] schlimmer geworden als die ersten.',
        21: 'Denn es wäre besser für sie, den Weg der Gerechtigkeit nicht erkannt zu haben, als ihn erkannt zu haben und sich von dem ihnen überlieferten, heiligen Gebot abzuwenden.',
        22: 'Ihnen ist das des wahren Sprichworts passiert: „Der Hund kehrt zurück zu seinem Erbrochenen“, und: „Die gebadete Sau zum Wälzen im Dreck.“',
    },
    3: {
        1: 'Geliebte [Geschwister], dies [ist] bereits der zweite Brief, den ich euch schreibe, womit ich euren unverfälschten Verstand durch eine Erinnerung wecke,',
        2: 'um an die von den heiligen Propheten zuvor gesagten Worte und an das von euren Aposteln [überlieferte] Gebot des Herrn und Retters zu erinnern,',
        3: 'damit ihr vor allem Folgendes wisst: dass in den letzten Tagen Spötter mit Spötterei kommen werden, die nach ihren eigenen Begierden leben',
        4: 'und sagen: „Wo ist die Verheißung seiner Ankunft? Denn seitdem die Väter entschlafen sind, bleibt alles so, wie [es war] seit Anbeginn der Schöpfung.“',
        5: 'Denen, die dies steif und fest behaupten, entgeht nämlich, dass es vorzeiten Himmel gab und eine Erde, die aus Wasser und durch Wasser Bestand hat durch das Gotteswort,',
        6: 'wodurch die damalige Welt mit Wasser geflutet wurde und unterging;',
        7: 'aber die jetzigen Himmel und die jetzige Erde sind durch dasselbe Wort aufbewahrt worden, für das Feuer aufbewahrt bis zum Tag des Gerichts und des Verderbens der gottlosen Menschen.',
        8: 'Aber dies Eine soll euch nicht entgehen, geliebte [Geschwister]: dass ein einziger Tag beim Herrn wie tausend Jahre und tausend Jahre wie ein einziger Tag [sind].',
        9: 'Der Herr verzögert die Verheißung nicht, wie einige es für eine Verzögerung halten, sondern er hat euch gegenüber Geduld, weil er nicht will, dass einige verloren gehen, sondern alle zur Buße gelangen.',
        10: 'Der Tag des Herrn wird aber kommen wie ein Dieb. An ihm werden die Himmel mit Getöse vergehen, und Himmelskörper werden verbrannt und aufgelöst werden, und die Erde und die Werke darin wird man nicht [mehr] finden.',
        11: 'Da dies alles in dieser Weise aufgelöst werden, was für [Leute] müsst ihr sein in heiligem Lebenswandel und Frömmigkeit,',
        12: 'während ihr die Ankunft von Gottes Tag erwartet und beschleunigt, aufgrund dessen die Himmel verbrennen und sich auflösen werden und Himmelskörper verglühen und schmelzen.',
        13: 'Gemäß seiner Verheißung erwarten wir aber neue Himmel und eine neue Erde, in denen Gerechtigkeit wohnt.',
        14: 'Darum, geliebte [Geschwister]: Da ihr diese [Dinge] erwartet, befleißigt euch, unbefleckt und unschuldig in Frieden von ihm gefunden zu werden,',
        15: 'und betrachtet die Geduld unseres Herrn als [eure] Rettung, so wie auch unser geliebter Bruder Paulus entsprechend der ihm verliehenen Weisheit euch geschrieben hat,',
        16: 'wie auch in allen Briefen, wenn er in ihnen darüber redet, in darin einiges schwer verständlich ist, die die Ungelernten und Ungefestigten verdrehen werden, wie auch die übrigen Schriften, zu ihrem eigenen Verderben.',
        17: 'Da ihr dies also bereits wisst, geliebte [Geschwister], hütet euch, damit ihr nicht [euren] eigenen Standpunkt verliert, indem ihr durch den Irrtum der Gesetzlosen verführt werdet,',
        18: 'und wachst in der Gnade und Erkenntnis unseres Herrn und Retters Jesus Christus! Ihm [sei] die Ehre, sowohl jetzt als auch bis zum Tag der Ewigkeit!',
    },
}
